// === Tab: mySketch ===
// Credit to the original sketch creator Antrague and previous forkers

let particles1 = [];
let num = 10000;
let counter = 0;

function setup() {
  createCanvas((16/9) * windowHeight, windowHeight);
  background(0);
  colorMode(HSB);
  // 可选：降低帧率省算力
  // frameRate(30);

  for (let i = 0; i < num; i++) {
    particles1.push(createVector(random(width), random(height)));
  }
}

function draw() {
  counter++;

  // 可选：拖影效果（降低越画越亮的感觉）
  // noStroke();
  // fill(0, 0, 0, 8);  // 透明度可调
  // rect(0, 0, width, height);

  // 颜色逻辑保留，但不再限制帧数
  if (counter < 10) stroke("blue");
  else stroke(50 + counter, 20, counter + 10, 20);

  for (let i = 0; i < num; i++) {
    let p = particles1[i];

    // 绘制
    if (counter > 10) point(p.x + random(-3, 13), p.y);
    else point(p.x + random(-3, 10), p.y + random(500));

    // 更新位置（流场）
    p.x += (noise(p.x / 200, p.y / 200, 300000) - 1) * 2;
    p.y += (noise(p.x / 200, p.y / 200, 30000) - 0.5) * 20;

    // 出界包回，避免粒子走丢
    if (p.x < 0) p.x += width;
    if (p.x > width) p.x -= width;
    if (p.y < 0) p.y += height;
    if (p.y > height) p.y -= height;
  }
}

function keyPressed() {
  save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg");
}

// 可选：窗口变动时保持 16:9 画布比例
function windowResized() {
  resizeCanvas((16/9) * windowHeight, windowHeight);
  // 重新铺一层背景避免拉伸残影
  background(0);
}

